import { useEffect, useMemo, useState } from 'react'
import { message, Upload } from 'antd'
import { fetchCompanyProfile, postConfigUploadImg } from '@/service/system.ts'
import Image from '@/components/Image'
import { useTranslation } from 'react-i18next'
import { PlusOutlined, DeleteOutlined } from '@ant-design/icons'
import { useCreation } from 'ahooks'
import { serverUrl } from '@/constants/env.ts'
import type { UploadFile, UploadProps } from 'antd/es/upload'
import styles from './index.module.less'

export interface IProps {
  value?: string[] | []
  fallbackImg?: string
  onChange?: (value: string[]) => void
  uploadConfig?: UploadProps
  uploadType?: 'image' | 'video'
  maxDimensions?: {
    width: number
    height: number
  }
  showImageDimensions?: boolean
}

export type IPropsUploadVideo = Omit<IProps, 'fallbackImg' | 'uploadType'>

const UploadWithForm = (props: IProps) => {
  const {
    value = [],
    onChange,
    fallbackImg,
    uploadConfig = {},
    uploadType = 'image',
    maxDimensions,
    showImageDimensions,
  } = props

  const { t } = useTranslation()
  const [loading, setLoading] = useState(false)
  const [fileList, setFileList] = useState<UploadFile[]>([])

  const isMultiple = useMemo(() => {
    return uploadConfig.multiple === true
  }, [uploadConfig])

  useEffect(() => {
    if (!isMultiple || !value?.length) {
      setFileList([])
      return
    }
    if (value?.length > 0) {
      const initFileList = value?.map((each) => {
        const srcUid = each.split('/')[3]
        return {
          uid: srcUid,
          status: 'done',
        }
      }) as UploadFile[]
      setFileList(initFileList)
      return
    }
    setFileList([])
  }, [value, isMultiple])

  const beforeUploadImg: UploadProps['beforeUpload'] = (file) => {
    const validPicType = ['image/png', 'image/jpg', 'image/jpeg']
    const { type, size } = file
    const isValidType = validPicType.includes(type)
    if (!isValidType) {
      message.info(t('palette.img_limit_format'))
      return Upload.LIST_IGNORE
    }
    const isLt4M = size / 1024 / 1024 <= 5
    if (!isLt4M) {
      message.info(t('palette.img_limit_size'))
      return Upload.LIST_IGNORE
    }
    // 检查图片尺寸
    if (maxDimensions) {
      const img = new window.Image()
      img.src = URL.createObjectURL(file)
      return new Promise((resolve) => {
        img.onload = () => {
          const { naturalWidth, naturalHeight } = img
          const { width: maxWidth, height: maxHeight } = maxDimensions
          if (naturalWidth > maxWidth || naturalHeight > maxHeight) {
            message.info(
              t('palette.img_limit_dimensions', {
                width: maxWidth,
                height: maxHeight,
              })
            )
            resolve(Upload.LIST_IGNORE)
          }
          resolve(true)
        }
      })
    }

    return true
  }

  const handleChangeImg: UploadProps['onChange'] = async (info) => {
    const { fileList } = info
    setFileList(fileList || [])
    const isAllUploadSuccess = fileList.every((f) => f.status === 'done')
    if (isAllUploadSuccess) {
      const res = await fetchCompanyProfile()
      if (res?.res?.data?.company) {
        const images = res?.res?.data?.company.images
        const uploadImgList = fileList.map((file) => {
          const uid = (file as UploadFile).uid
          return images.find((each) => each.name === uid)?.url || ''
        })
        onChange?.(uploadImgList)
      }
      message.success(t('palette.upload_success'))
      setLoading(false)
      return
    }
    const isHasError = fileList.some((f) => f.status === 'error')
    if (isHasError) {
      message.error(t('palette.upload_error'))
      setLoading(false)
    }
  }

  const customRequest: UploadProps['customRequest'] = async (option) => {
    setLoading(true)
    const f = new FormData()
    f.set('file', option.file)
    const uid = (option.file as UploadFile).uid
    try {
      const res = await postConfigUploadImg(uid, f)
      if (res?.res?.data === 'Image has been successfully uploaded') {
        option.onSuccess?.('success')
        return
      }
      option.onError?.(Error('error'))
    } catch (e) {
      option.onError?.(Error((e as Error).message))
    }
  }

  const handleRemoveImage = (src: string) => {
    const srcUid = src.split('/')[3]
    const newValue = value?.filter((each) => each !== src)
    onChange?.(newValue as string[])
    const newFileList = fileList.filter((each) => each.uid !== srcUid)
    setFileList(newFileList)
  }

  const [dimensionsList, setDimensionsList] = useState<
    Record<string, { width: number; height: number }>
  >({})

  const UploadDom = useCreation(() => {
    const addDom = (
      <div className={styles.area}>
        <PlusOutlined />
        <span className={styles.text}>{t('operation.upload')}</span>
      </div>
    )

    if (uploadType === 'image') {
      if (!value?.length && fallbackImg) {
        return (
          <div className={styles.uploadImgWrapper}>
            <div>
              <div className={styles.uploadImgItem}>
                <Image
                  fallbackImg={fallbackImg}
                  alt="background img"
                  className={styles.uploadImg}
                  onLoad={(e) => {
                    const img = e.currentTarget
                    setDimensionsList((prev) =>
                      prev[fallbackImg]
                        ? prev
                        : {
                            ...prev,
                            [fallbackImg]: {
                              width: img.naturalWidth,
                              height: img.naturalHeight,
                            },
                          }
                    )
                  }}
                />
              </div>
              {showImageDimensions && (
                <div className={styles.imageDimensions}>
                  {dimensionsList[fallbackImg]?.width || '-'}*
                  {dimensionsList[fallbackImg]?.height || '-'}
                </div>
              )}
            </div>
          </div>
        )
      }

      return (
        <div className={styles.uploadImgWrapper}>
          {value?.length > 0
            ? value.map((v, idx) => {
                return (
                  <div key={idx}>
                    <div className={styles.uploadImgItem}>
                      <Image
                        fallbackImg={fallbackImg}
                        src={v}
                        alt="background img"
                        className={styles.uploadImg}
                        onClick={(e) => {
                          if (isMultiple) return e.stopPropagation()
                        }}
                        onLoad={(e) => {
                          const img = e.currentTarget
                          setDimensionsList((prev) =>
                            prev[v]
                              ? prev
                              : {
                                  ...prev,
                                  [v]: {
                                    width: img.naturalWidth,
                                    height: img.naturalHeight,
                                  },
                                }
                          )
                        }}
                      />
                      {isMultiple && (
                        <DeleteOutlined
                          className={styles.removeIcon}
                          onClick={(e) => {
                            e.stopPropagation()
                            handleRemoveImage(v)
                          }}
                        />
                      )}
                    </div>
                    {showImageDimensions && (
                      <div className={styles.imageDimensions}>
                        {dimensionsList[v]?.width || '-'}*
                        {dimensionsList[v]?.height || '-'}
                      </div>
                    )}
                  </div>
                )
              })
            : null}
          {(value?.length || 0) >= (uploadConfig.maxCount || 1) ? null : (
            <div>
              {addDom}
              {showImageDimensions && (
                <div className={styles.imageDimensions}></div>
              )}
            </div>
          )}
        </div>
      )
    }
    return (
      <div className={styles.uploadImgWrapper}>
        <div>
          <div className={styles.uploadImgItem}>
            {value?.length > 0 ? (
              <video
                className={styles.uploadImg}
                src={`${serverUrl}${value?.[0]}`}
                onClick={(e) => e.preventDefault()}
                onLoadedMetadata={(e) => {
                  const video = e.currentTarget
                  setDimensionsList((prev) =>
                    prev[value?.[0]]
                      ? prev
                      : {
                          ...prev,
                          [value?.[0]]: {
                            width: video.videoWidth,
                            height: video.videoHeight,
                          },
                        }
                  )
                }}
              />
            ) : (
              addDom
            )}
          </div>
          {showImageDimensions && (
            <div className={styles.imageDimensions}>
              {value?.length > 0 ? (
                <div>
                  {dimensionsList[value?.[0]]?.width || '-'}*
                  {dimensionsList[value?.[0]]?.height || '-'}
                </div>
              ) : null}
            </div>
          )}
        </div>
      </div>
    )
  }, [
    uploadType,
    value,
    uploadConfig.maxCount,
    fallbackImg,
    t,
    isMultiple,
    dimensionsList,
    showImageDimensions,
  ])

  return (
    <Upload
      fileList={fileList}
      name="avatar"
      showUploadList={false}
      beforeUpload={beforeUploadImg}
      onChange={handleChangeImg}
      customRequest={customRequest}
      disabled={loading}
      {...uploadConfig}
    >
      {UploadDom}
    </Upload>
  )
}

const UploadVideo = (props: IPropsUploadVideo) => {
  const { t } = useTranslation()

  const beforeUploadVideo: UploadProps['beforeUpload'] = (file) => {
    const allowedTypes = [
      'video/mp4',
      'video/x-msvideo', // avi
      'video/x-matroska', // mkv
      'video/quicktime', // mov
      'video/x-ms-wmv', // wmv
    ]
    const fileTypeValid = allowedTypes.includes(file.type)
    if (!fileTypeValid) {
      message.error(t('palette.video_limit_format'))
      return Upload.LIST_IGNORE
    }
    const isLt4M = file.size / 1024 / 1024 <= 5
    if (!isLt4M) {
      message.info(t('palette.video_limit_size'))
      return Upload.LIST_IGNORE
    }
    const { maxDimensions } = props
    if (maxDimensions) {
      const video = document.createElement('video')
      video.src = URL.createObjectURL(file)
      return new Promise((resolve) => {
        video.onloadedmetadata = () => {
          const { videoWidth, videoHeight } = video
          const { width: maxWidth, height: maxHeight } = maxDimensions
          if (videoWidth > maxWidth || videoHeight > maxHeight) {
            message.info(
              t('palette.video_limit_dimensions', {
                width: maxWidth,
                height: maxHeight,
              })
            )
            resolve(Upload.LIST_IGNORE)
          }
          resolve(true)
        }
      })
    }
    return true
  }

  return (
    <UploadWithForm
      {...props}
      uploadConfig={{
        ...props.uploadConfig,
        beforeUpload: beforeUploadVideo,
      }}
      uploadType="video"
    />
  )
}

UploadWithForm.UploadVideo = UploadVideo

export default UploadWithForm
