import ImageCoreBlock from '@/components/CoreBlock/ImageCoreBlock'
import { IRenderBlockInfo } from '@/types/block'

const MemberPriceIcon = (props: IRenderBlockInfo) => {
  const { style, props: blockProps, data } = props
  const extraStyle = data?.style || {}

  return (
    <ImageCoreBlock
      src={blockProps?.imgUrl}
      style={{ ...style, ...extraStyle }}
      fallbackImg={blockProps?.defaultImg}
      alt="member price icon default image"
    />
  )
}

export default MemberPriceIcon
