import { Col, Radio, Row } from 'antd'
import { useTranslation } from 'react-i18next'
import { useAppDispatch, useTypedSelector } from '@/store'
import { initVideoStyle } from '@/constants/BlockInitStyle.ts'
import type { RadioGroupProps } from 'antd/es/radio'
import { actions } from '@/store/slices/palette.slice.ts'
import { useMemo } from 'react'

const { Group: RadioGroup } = Radio

const VideoProperty = () => {
  const { t } = useTranslation()
  const { currentBlock, viewportWidth, viewportHeight } = useTypedSelector(
    (state) => state.paletteSlice
  )
  const dispatch = useAppDispatch()

  const handleChangeDirection: RadioGroupProps['onChange'] = (v) => {
    const newSize = v.target.value
      ? { width: viewportWidth, height: viewportHeight, top: 0, left: 0 }
      : { width: initVideoStyle.width, height: initVideoStyle.height }
    const newCurrentBlock = {
      ...currentBlock,
      style: {
        ...currentBlock.style,
        ...newSize,
      },
      props: {
        ...currentBlock.props,
        isFullPage: v.target.value,
      },
    }
    dispatch(actions.setCurrentBlock(newCurrentBlock))
  }

  const currentSize = useMemo(() => {
    return {
      width: currentBlock.style.width,
      height: currentBlock.style.height,
    }
  }, [currentBlock])

  const isFullPage = useMemo(() => {
    return (
      currentSize.width === viewportWidth &&
      currentSize.height === viewportHeight
    )
  }, [currentSize])

  return (
    <Row align="middle">
      <Col span={10}>{t('blocks.props_fullPage')}:</Col>
      <Col span={14}>
        <RadioGroup
          onChange={handleChangeDirection}
          value={isFullPage || !!currentBlock.props?.isFullPage}
        >
          <Radio value={false}>{t('blocks.value_no')}</Radio>
          <Radio value={true}>{t('blocks.value_yes')}</Radio>
        </RadioGroup>
      </Col>
    </Row>
  )
}

export default VideoProperty
