import { Col, ColorPicker, Row, Space } from 'antd'
import { CSSKey, CSSValueUnion } from '@/types/block'
import type { CSSProperties } from 'react'
import { useTranslation } from 'react-i18next'

interface IProps {
  cssKey: CSSKey[]
  data: {
    style: Partial<Record<CSSKey, CSSValueUnion>>
    label?: Partial<Record<CSSKey, string>>
  }
  onChange: (css: CSSProperties) => void
}

const ColorStyleChanger = (props: IProps) => {
  const { t } = useTranslation()

  const { cssKey, data, onChange } = props

  const changeColor = (newStyle: CSSProperties) => {
    onChange(newStyle)
  }

  return (
    <Space direction="vertical" size={8}>
      {cssKey.map((key, i) => {
        return (
          <Row align="middle" key={i}>
            <Col span={10}>{data.label?.[key] || t(`style.${key}`)}:</Col>
            <Col span={14}>
              <ColorPicker
                destroyTooltipOnHide
                showText
                value={data.style[key] as string}
                onChange={(v) => changeColor({ [key]: `#${v.toHex()}` })}
              />
            </Col>
          </Row>
        )
      })}
    </Space>
  )
}

export default ColorStyleChanger
