import { useMemo } from 'react'
import UploadWithForm, {
  type IProps as IUploadImage,
  IPropsUploadVideo,
} from '../UploadWithForm'
import { useAppDispatch, useTypedSelector } from '@/store'
import { actions } from '@/store/slices/palette.slice.ts'
import { useTranslation } from 'react-i18next'
import { Col, Row } from 'antd'

type IUploadProperty = IUploadImage | IPropsUploadVideo

const Uploader = (props: IUploadProperty) => {
  const { t } = useTranslation()
  const { currentBlock, width, height } = useTypedSelector(
    (state) => state.paletteSlice
  )
  const dispatch = useAppDispatch()

  const isMultiple = useMemo(() => {
    return !!props.uploadConfig?.multiple
  }, [props])

  const fallbackImg = useMemo(() => {
    return isMultiple ? undefined : currentBlock?.props?.defaultImg
  }, [currentBlock, isMultiple])

  const uploadValue = useMemo(() => {
    if (isMultiple) return currentBlock?.props?.images || []
    return currentBlock?.props?.imgUrl ? [currentBlock?.props?.imgUrl] : []
  }, [isMultiple, currentBlock])

  const uploadImageToCurrentBlock = (val: string[]) => {
    if (isMultiple) {
      dispatch(actions.editCurrentBlockProps({ images: val }))
      return
    }
    const imgUrl = val?.[0]
    dispatch(actions.editCurrentBlockProps({ imgUrl, defaultImg: undefined }))
  }

  return (
    <Row align="top">
      <Col span={10}>{t('operation.upload')}:</Col>
      <Col span={14}>
        <UploadWithForm
          fallbackImg={fallbackImg}
          value={uploadValue}
          onChange={uploadImageToCurrentBlock}
          maxDimensions={{
            width,
            height,
          }}
          showImageDimensions={true}
          {...props}
          uploadType="image"
        />
      </Col>
    </Row>
  )
}

const BlockUploadImage = (props: IUploadProperty) => {
  return <Uploader {...props} />
}

export default BlockUploadImage
