export const posLanguageCode2emenuLanguageCode = {
  en: 'en',
  'zh-cn': 'zh',
  'zh-Hant': 'zh-Hant',
  French: 'fr',
  jp: 'jp',
  ru: 'ru',
  es: 'es',
  vi: 'vi',
  th: 'th',
  ko: 'ko',
}

export const transformLanguageCode = (
  lang: keyof typeof posLanguageCode2emenuLanguageCode
) => {
  return posLanguageCode2emenuLanguageCode[lang] || lang
}
