const getSessionKeyViaMessage = (
  cb?: (sessionKey: string | undefined) => void
) => {
  const getSessionKey = (event: { data: { [key: string]: string } }) => {
    if (event?.data?.type === 'sessionKey') {
      const sessionKey = event.data.data
      cb?.(sessionKey)
    }
    window.removeEventListener('message', getSessionKey)
  }
  window.parent.postMessage({ type: 'getSessionKey' }, '*')
  window.addEventListener('message', getSessionKey)
}

export default getSessionKeyViaMessage
