import { Col, Row, InputNumber, Space } from 'antd'
import { useTranslation } from 'react-i18next'
import getCssValue from '@/utils/getCssValue.ts'
import { CSSProperties } from 'react'
import { CSSKey, CSSValues } from '@/types/block'

interface IProps {
  cssKey: CSSKey[]
  data: {
    style: CSSProperties
    min?: CSSValues
    max?: CSSValues
    step?: number
  }
  onChange: (css: CSSProperties) => void
}

interface IPixelProps {
  key: CSSKey
  v: number | null
  min: number
  max: number
}

const PixelStyleChanger = (props: IProps) => {
  const { cssKey, data, onChange } = props
  const { t } = useTranslation()

  const changeBlockStyle = (args: IPixelProps) => {
    const { key, v, min, max } = args
    let actualVal = v || 0
    if (actualVal <= min) actualVal = min
    if (actualVal >= max) actualVal = max
    onChange({ [key]: actualVal })
  }

  return (
    <Space direction="vertical" size={8}>
      {cssKey.map((key, i) => {
        const min = getCssValue(data?.min?.[key]) || 0
        const max = getCssValue(data?.max?.[key]) || 9999
        return (
          <Row align="middle" key={i}>
            <Col span={10}>{t(`style.${key}`)}:</Col>
            <Col span={14}>
              <InputNumber
                value={getCssValue(data.style[key])}
                step={data.step || 1}
                min={min}
                max={max}
                onChange={(v) => changeBlockStyle({ key, v, min, max })}
                addonAfter="px"
              />
            </Col>
          </Row>
        )
      })}
    </Space>
  )
}

export default PixelStyleChanger
