import React, { memo, useMemo } from 'react'
import type { IRenderBlockInfo } from '@/types/block'
import { serverUrl } from '@/constants/env.ts'

const Video = (props: IRenderBlockInfo) => {
  const { style, props: blockProps } = props

  const videoProps = useMemo(() => {
    const newProps = blockProps ? { ...blockProps } : {}
    delete newProps.videoUrl
    delete newProps.visible
    delete newProps.isFullPage
    return newProps as React.VideoHTMLAttributes<HTMLVideoElement>
  }, [blockProps])

  return (
    <video
      {...videoProps}
      style={style}
      src={`${serverUrl}${blockProps?.videoUrl}`}
    >
      Your browser does not support the video tag.
    </video>
  )
}

export default memo(Video)
