import { useTypedSelector } from '@/store'
import { IRenderBlockInfo } from '@/types/block'
import { memo, useMemo } from 'react'
import { useTranslation } from 'react-i18next'

const DishName = (props: IRenderBlockInfo) => {
  const { t, i18n } = useTranslation()
  const { style, props: blockProps } = props
  const { menus } = useTypedSelector((state) => state.menuSlice)

  const currentDish = useMemo(() => {
    const allDishes = menus[0]?.menuGroups?.flatMap((group) =>
      group.menuCategories?.flatMap((category) => category.saleItems)
    )
    return allDishes?.find((dish) => dish?.id === Number(blockProps?.itemId))
  }, [menus, blockProps?.itemId])

  const dishName = useMemo(() => {
    const fieldDisplayNameGroups = currentDish?.fieldDisplayNameGroups
    const currentFieldDisplayNameGroup = fieldDisplayNameGroups?.find(
      (group) => group.fieldName === 'name'
    )
    const currentFieldDisplayName =
      currentFieldDisplayNameGroup?.fieldDisplayNames?.find((displayName) => {
        return (
          displayName.languageCode?.toLowerCase().substring(0, 2) ===
          i18n.language?.toLowerCase()?.substring(0, 2)
        )
      })
    return (
      currentFieldDisplayName?.name ||
      currentDish?.name ||
      t('blocks.dishName_label')
    )
  }, [currentDish, i18n.language, t])

  return (
    <div style={style}>
      <span>{dishName}</span>
    </div>
  )
}

export default memo(DishName)
