import { memo, type MouseEvent } from 'react'
import ImageCoreBlock from '@/components/CoreBlock/ImageCoreBlock.tsx'
import type { IRenderBlockInfo } from '@/types/block'
import { useAppDispatch, useTypedSelector } from '@/store'
import { actions } from '@/store/slices/palette.slice.ts'
import type { IBusinessComp, ITemplateData } from '@/types/template'

const MenuIndicator = (props: IRenderBlockInfo) => {
  const { style, props: blockProps } = props
  const dispatch = useAppDispatch()
  const { currentBlock, globalBlocks } = useTypedSelector(
    (state) => state.paletteSlice
  )

  const handleClick = (event: MouseEvent<HTMLDivElement>) => {
    event.stopPropagation()
    const linkIds = currentBlock.props?.linkIds
    if (currentBlock.component === 'ExpandMenu') {
      const newGlobalBlocks = globalBlocks?.map((b) => {
        if (b.id === currentBlock.id) {
          return {
            ...b,
            style: {
              ...b.style,
              visibility: 'hidden',
            },
          }
        }
        if (linkIds?.includes(b.id)) {
          return {
            ...b,
            style: {
              ...b.style,
              visibility: 'visible',
            },
          }
        }
        return b
      })
      dispatch(
        actions.setGlobalBlocks(
          newGlobalBlocks as ITemplateData['globalBlocks']
        )
      )
      dispatch(actions.setCurrentBlock({} as IBusinessComp))
      return
    }
    if (currentBlock.component === 'NarrowMenu') {
      const newGlobalBlocks = globalBlocks?.map((b) => {
        if (b.id === currentBlock.id) {
          return {
            ...b,
            style: {
              ...b.style,
              visibility: 'hidden',
            },
          }
        }
        if (linkIds?.includes(b.id)) {
          return {
            ...b,
            style: {
              ...b.style,
              visibility: b.component === 'MenuList' ? 'hidden' : 'visible',
            },
          }
        }
        return b
      })
      dispatch(
        actions.setGlobalBlocks(
          newGlobalBlocks as ITemplateData['globalBlocks']
        )
      )
      dispatch(actions.setCurrentBlock({} as IBusinessComp))
      return
    }
  }

  return (
    <div
      style={{
        width: style.width,
        height: style.height,
        opacity: style.opacity,
      }}
    >
      <ImageCoreBlock
        src={blockProps?.imgUrl}
        style={style}
        fallbackImg={blockProps?.defaultImg}
        alt="expand menu image"
      />
      {currentBlock.id === props.id && (
        <div
          onClick={handleClick}
          style={{
            position: 'absolute',
            inset: 0,
            zIndex: 99,
          }}
        />
      )}
    </div>
  )
}

export default memo(MenuIndicator)
