import { memo } from 'react'
import type { IRenderBlockInfo } from '@/types/block'
import { Carousel as AntdCarousel } from 'antd'
import Image from '@/components/Image'
import { useTranslation } from 'react-i18next'
import styles from './index.module.less'

const Carousel = (props: IRenderBlockInfo) => {
  const { style, props: blockProps } = props
  const { t } = useTranslation()

  return (
    <div style={style} className={styles.carouselWrapper}>
      {!blockProps?.images?.length ? (
        <div className={styles.defaultText}>{t('blocks.carousel_label')}</div>
      ) : (
        <AntdCarousel {...blockProps} draggable={false}>
          {blockProps?.images?.map((v) => {
            return <Image key={v} src={v} alt="Carousel img" />
          })}
        </AntdCarousel>
      )}
    </div>
  )
}

export default memo(Carousel)
