import { useTypedSelector } from '@/store'
import { IRenderBlockInfo } from '@/types/block'
import { haveOptionsPrice } from '@/utils'
import { memo, useMemo } from 'react'
import { useTranslation } from 'react-i18next'

const SalePrice = (props: IRenderBlockInfo) => {
  const { t } = useTranslation()
  const { style, props: blockProps } = props
  const { menus } = useTypedSelector((state) => state.menuSlice)

  const currentDish = useMemo(() => {
    const allDishes = menus[0]?.menuGroups?.flatMap((group) =>
      group.menuCategories?.flatMap((category) => category.saleItems)
    )
    return allDishes?.find((dish) => dish?.id === Number(blockProps?.itemId))
  }, [menus, blockProps?.itemId])

  const displayText = useMemo(() => {
    if (currentDish?.marketPriceItem) {
      return t('display.market_price')
    }

    if (currentDish?.itemPrices?.length) {
      const { minPrice, isPriceAllZero } = currentDish.itemPrices.reduce(
        (
          acc: { minPrice: number | undefined; isPriceAllZero: boolean },
          item
        ) => {
          const currentPrice = item.price ?? 0
          if (acc.minPrice === undefined) {
            acc.minPrice = currentPrice
          } else if (acc.minPrice > currentPrice) {
            acc.minPrice = currentPrice
          }
          if (currentPrice > 0) {
            acc.isPriceAllZero = false
          }
          return acc
        },
        { minPrice: undefined, isPriceAllZero: true }
      )
      return isPriceAllZero ? '$0.00' : `$${minPrice?.toFixed(2)}+`
    }

    let normalPrice = currentDish?.price
      ? `$${currentDish.price.toFixed(2)}`
      : '$0.00'
    if (haveOptionsPrice(currentDish?.options)) {
      normalPrice = `${normalPrice}+`
    }
    return normalPrice
  }, [currentDish])

  return (
    <div style={style}>
      <span>{displayText}</span>
    </div>
  )
}

export default memo(SalePrice)
