import PixelStyleChanger from './PixelStyleChanger'
import { useAppDispatch, useTypedSelector } from '@/store'
import { actions } from '@/store/slices/palette.slice.ts'
import NP from 'number-precision'
import getCssValue from '@/utils/getCssValue.ts'
import type { CSSProperties } from 'react'
import type { CSSKey } from '@/types/block'

interface IProps {
  cssKey?: CSSKey[]
}

const ChangePosition = (props: IProps) => {
  const { cssKey = ['left', 'top'] } = props
  const { currentBlock, viewportWidth, viewportHeight } = useTypedSelector(
    (state) => state.paletteSlice
  )
  const dispatch = useAppDispatch()

  const onPositionChange = (newSize: CSSProperties) => {
    dispatch(actions.editCurrentBlockStyle(newSize))
  }

  return (
    <PixelStyleChanger
      cssKey={cssKey}
      onChange={onPositionChange}
      data={{
        style: currentBlock.style,
        max: {
          left: NP.minus(
            viewportWidth,
            getCssValue(currentBlock?.style?.width)
          ),
          top: NP.minus(
            viewportHeight,
            getCssValue(currentBlock?.style?.height)
          ),
        },
      }}
    />
  )
}

export default ChangePosition
