import { createSlice } from '@reduxjs/toolkit'
import type { PayloadAction } from '@reduxjs/toolkit'
import { IProductGrouping } from '@/types/productGrouping'

const initialState: IProductGrouping = {
  selectedMenu: [],
  selectedCategory: undefined,
}

export const productGrouping = createSlice({
  name: 'productGrouping',
  initialState,
  reducers: {
    setSelectedMenu: (
      state,
      action: PayloadAction<IProductGrouping['selectedMenu']>
    ) => {
      state.selectedMenu = action.payload
    },
    setSelectedCategory(
      state,
      action: PayloadAction<IProductGrouping['selectedCategory']>
    ) {
      state.selectedCategory = action.payload
    },
  },
})

export const actions = productGrouping.actions

export default productGrouping.reducer
