import { Post, Get } from '@/utils/request.ts'
import type { ICompany } from '@/types/service'

export function fetchCompanyProfile() {
  return Get<ICompany>('/company/profile/fetch')
}

export function postConfigUploadImg(type: string, data: object) {
  return Post<string>(
    `${
      import.meta.env.DEV
        ? `${import.meta.env.VITE_SERVER_URL}webapp`
        : '/kpos/webapp'
    }/file/image/upload/kiosk/${type}`,
    data,
    {
      baseURL: '/',
    }
  )
}
