import PixelStyleChanger from './PixelStyleChanger'
import { useAppDispatch, useTypedSelector } from '@/store'
import { type CSSProperties } from 'react'
import { actions } from '@/store/slices/palette.slice.ts'
import type { CSSKey } from '@/types/block'
import getCssValue from '@/utils/getCssValue'

interface IProps {
  cssKey?: CSSKey[]
}

const ChangeFontSize = (props: IProps) => {
  const { cssKey = ['fontSize'] } = props
  const { currentBlock, viewportWidth, viewportHeight } = useTypedSelector(
    (state) => state.paletteSlice
  )
  const dispatch = useAppDispatch()

  const onSizeChange = (newSize: CSSProperties) => {
    const div = document.createElement('div')
    div.style.fontSize = getCssValue(newSize.fontSize) + 'px'
    div.style.lineHeight = getCssValue(currentBlock.style.lineHeight) + ''
    div.style.position = 'absolute'
    div.style.visibility = 'hidden'
    div.textContent = (currentBlock.props?.text as string) || ''
    document.body.appendChild(div)
    const rect = div.getBoundingClientRect()
    document.body.removeChild(div)
    dispatch(
      actions.editCurrentBlockStyle({
        ...newSize,
        width: rect.width,
        height: rect.height,
      })
    )
  }

  return (
    <PixelStyleChanger
      cssKey={cssKey}
      onChange={onSizeChange}
      data={{
        style: currentBlock.style,
        min: {
          width: currentBlock.style.minWidth,
          height: currentBlock.style.minHeight,
        },
        max: {
          width: viewportWidth,
          height: viewportHeight,
        },
      }}
    />
  )
}

export default ChangeFontSize
