import { IRenderBlockInfo } from '@/types/block'
import register from '@/utils/blockRegister'

const MemberPrice = (props: IRenderBlockInfo) => {
  const { style, children } = props

  return (
    <div style={style}>
      {children?.map((block) => {
        const { component } = block
        const blockInfo = register.getBlock(component)
        return blockInfo.render({
          ...block,
          data: {
            itemId: props.props?.itemId,
            ...(component === 'MemberPriceIcon'
              ? {
                  style: block.style,
                }
              : {}),
          },
        })
      })}
    </div>
  )
}

export default MemberPrice
