import { ICategory, IGroup, IItem } from '@/types/service'
import { getI18n } from 'react-i18next'
import {
  posLanguageCode2emenuLanguageCode,
  transformLanguageCode,
} from './transformLanguageCode'

export const addI18nResources = (menuGroups: IGroup[]) => {
  const i18n = getI18n()

  const addTranslation = (item: IGroup | ICategory | IItem, ns: string) => {
    item.fieldDisplayNameGroups
      ?.find((i) => i.fieldName === 'name')
      ?.fieldDisplayNames.forEach((e) => {
        i18n.addResources(
          transformLanguageCode(
            e.languageCode as keyof typeof posLanguageCode2emenuLanguageCode
          ),
          ns,
          {
            [item.id]: e.name || item.name,
          }
        )
      })
  }

  menuGroups.forEach((g) => {
    addTranslation(g, 'group')
    g.menuCategories?.forEach((c) => {
      addTranslation(c, 'category')
      c.saleItems?.forEach((s) => {
        addTranslation(s, 'dish')
      })
    })
  })

  // 触发多语言更新
  i18n.changeLanguage(i18n.language)
}
