import type { PayloadAction } from '@reduxjs/toolkit'
import { createSlice } from '@reduxjs/toolkit'
import {
  IBusinessComp,
  IBusinessCompProps,
  ISingleCategoryData,
  ITemplateData,
} from '@/types/template'
import type { CSSProperties } from 'react'
import type { AppThunk } from '@/store'
import { getEMenuProConfig, setEMenuProConfig } from '@/service/setting.ts'
import { message } from 'antd'
import type { IConfigData, IGroup } from '@/types/service'
import { actions as productGroupingActions } from './productGrouping.slice.ts'
import getSessionKeyViaMessage from '@/utils/getSessionKeyViaMessage.ts'
import register from '@/utils/blockRegister.ts'
import { nanoid } from 'nanoid'
import { VIEWPORT_HEIGHT, VIEWPORT_WIDTH } from '@/constants/Viewport.ts'
import { IProductGrouping } from '@/types/productGrouping'
import packageJson from '../../../package.json'

const DEV_SESSION_KEY = localStorage.getItem('sessionKey') || ''

const initialState: ITemplateData = {
  spinning: false,
  version: packageJson.version,
  width: 1920,
  height: 1200,
  viewportWidth: VIEWPORT_WIDTH,
  viewportHeight: VIEWPORT_HEIGHT,
  direction: 'horizontal',
  status: 'draft',
  aspectRatio: '16 / 10',
  // 全量数据
  globalData: [] as ITemplateData['globalData'],
  // 全局组件
  globalBlocks: [] as ITemplateData['globalBlocks'],
  // 单页数据
  currentPageData: {} as ITemplateData['currentPageData'],
  // 单个组件数据
  currentBlock: {} as IBusinessComp,
  // 数据库是否有数据
  isHasTemplate: false,
}

export const paletteSlice = createSlice({
  name: 'paletteSlice',
  initialState,
  reducers: {
    setSpinning(state, action: PayloadAction<ITemplateData['spinning']>) {
      state.spinning = action.payload
    },
    setInitData(state, action: PayloadAction<Partial<ITemplateData>>) {
      return { ...state, ...action.payload }
    },
    setTemplateWidth(state, action: PayloadAction<ITemplateData['width']>) {
      state.width = action.payload
    },
    setTemplateHeight(state, action: PayloadAction<ITemplateData['height']>) {
      state.height = action.payload
    },
    setDirection(state, action: PayloadAction<ITemplateData['direction']>) {
      state.direction = action.payload
    },
    setViewPortSize(
      state,
      action: PayloadAction<{ viewportWidth: number; viewportHeight: number }>
    ) {
      state.viewportWidth = action.payload.viewportWidth
      state.viewportHeight = action.payload.viewportHeight
    },
    setAllGlobalData(
      state,
      action: PayloadAction<ITemplateData['globalData']>
    ) {
      state.globalData = action.payload
    },
    setCurrentPageData(
      state,
      action: PayloadAction<ITemplateData['currentPageData']>
    ) {
      state.currentPageData = action.payload
    },
    // 同步当前页数据到全局中
    syncPageDataToGroup(state) {
      const { currentPageData, globalData } = state
      const { groupId, categoryId, id } = currentPageData
      state.globalData = globalData.map((g) => {
        if (g.groupId !== groupId) return g
        return {
          ...g,
          children: g.children.map((c) => {
            return c.categoryId === categoryId
              ? {
                  ...c,
                  pageData: c.pageData.map((p) =>
                    p.id === id ? currentPageData : p
                  ),
                }
              : c
          }),
        }
      })
    },
    setCurrentBlock(
      state,
      action: PayloadAction<ITemplateData['currentBlock']>
    ) {
      state.currentBlock = action.payload
    },
    removeCurrentBlock(
      state,
      action: PayloadAction<ITemplateData['currentBlock']>
    ) {
      const { currentPageData, globalBlocks } = state
      const removeBlock = action.payload
      const originalBlockInfo = register.getBlock(removeBlock.component)
      if (!originalBlockInfo.isGlobalBlock) {
        state.currentPageData = {
          ...currentPageData,
          children: currentPageData?.children?.filter(
            (b) => b.id !== removeBlock.id
          ),
        }
      } else {
        state.globalBlocks = globalBlocks?.filter(
          (b) => b.id !== removeBlock.id
        )
      }
    },
    editCurrentBlockProps(state, action: PayloadAction<IBusinessCompProps>) {
      state.currentBlock = {
        ...state.currentBlock,
        props: {
          ...(state.currentBlock.props || {}),
          ...action.payload,
        },
      }
    },
    editCurrentBlockStyle(state, action: PayloadAction<CSSProperties>) {
      state.currentBlock = {
        ...state.currentBlock,
        style: {
          ...(state.currentBlock.style || {}),
          ...action.payload,
        },
      }
    },
    syncBlockDataToPage(
      state,
      action: PayloadAction<ITemplateData['currentBlock']>
    ) {
      state.currentPageData = {
        ...state.currentPageData,
        children: state.currentPageData.children?.map((b) => {
          return b.id === action.payload.id ? action.payload : b
        }),
      }
    },
    changeTemplateStatus(
      state,
      action: PayloadAction<ITemplateData['status']>
    ) {
      state.status = action.payload
    },
    setInitGlobalBlocks(state) {
      const globalBlocksInfo = [
        ...(register.getAllBlocks()?.entries() || []),
      ].filter(([, block]) => {
        return (
          block.isGlobalBlock &&
          !block.isChildren &&
          block.component !== 'ChangePartySize' // 目前针对品类模式不自动加入选择人数
        )
      })
      function makeUpInitGlobalBlock(
        blocks: typeof globalBlocksInfo
      ): IBusinessComp[] {
        const tempGlobalBlocksData = [] as IBusinessComp[]
        blocks.forEach(([, block]) => {
          const globalBlockItem = {
            id: nanoid(),
            component: block.component,
            style: {
              ...block.style,
            },
            props: block.props,
            children: block.children?.map((child) => {
              const childBlockInfo = register.getBlock(child)
              return {
                id: nanoid(),
                component: child,
                style: childBlockInfo.style,
                props: childBlockInfo.props,
              }
            }),
          } as IBusinessComp
          if (!block.linkComponents?.length) {
            tempGlobalBlocksData.push(globalBlockItem)
          } else {
            const tempLinkComponentData = [globalBlockItem] as IBusinessComp[]
            block?.linkComponents.forEach((blockType) => {
              const linkComponentInfo = [
                ...(register.getAllBlocks()?.entries() || []),
              ].filter(([, block]) => {
                return block.component === blockType
              })
              const res = makeUpInitGlobalBlock(linkComponentInfo)
              tempLinkComponentData.push(res[0])
            })
            const blockIds = tempLinkComponentData.map((b) => b.id)
            const finalLinkComponentData = tempLinkComponentData.map((b) => {
              return {
                ...b,
                props: {
                  ...b.props,
                  linkIds: blockIds.filter((id) => id !== b.id),
                },
              }
            })
            tempGlobalBlocksData.push(...finalLinkComponentData)
          }
        })
        return tempGlobalBlocksData
      }
      state.globalBlocks = makeUpInitGlobalBlock(globalBlocksInfo)
    },
    setGlobalBlocks(
      state,
      action: PayloadAction<ITemplateData['globalBlocks']>
    ) {
      state.globalBlocks = action.payload
    },
    changeGlobalDataAfterSortMenu(
      state,
      action: PayloadAction<IProductGrouping['selectedMenu']>
    ) {
      state.globalData = action.payload.map((group) => {
        const sameGroupData = state.globalData.find(
          (g) => g.groupId === String(group.id)
        )
        if (!sameGroupData) {
          return {
            groupId: String(group.id),
            groupName: group.name,
            children: group.menuCategories.map((category) => {
              return {
                categoryId: String(category.id),
                categoryName: category.name,
                pageData: [],
              }
            }),
          }
        }
        // 处理新增类或者删除类情况
        const selectedCategory = group.menuCategories
        const savedGroupingCategory = sameGroupData.children
        const newGroupingCategory = selectedCategory.reduce((pre, cur) => {
          const isSameCategory = savedGroupingCategory.find(
            (c) => c.categoryId === String(cur.id)
          )
          if (isSameCategory) return pre.concat(isSameCategory)
          const currentAddCategory = {
            categoryId: String(cur.id),
            categoryName: cur.name,
            pageData: [],
          }
          return pre.concat(currentAddCategory)
        }, [] as ISingleCategoryData[])
        return {
          ...sameGroupData,
          children: newGroupingCategory,
        }
      })
    },
    syncGlobalBlocks(
      state,
      action: PayloadAction<ITemplateData['currentBlock']>
    ) {
      state.globalBlocks = state.globalBlocks?.map((b) => {
        return b.id === action.payload.id ? action.payload : b
      })
    },
  },
})

export const actions = paletteSlice.actions

export default paletteSlice.reducer

const fetchEMenuProConfig = (): AppThunk => async (dispatch) => {
  const handleFetch = async (sessionKey?: string | undefined) => {
    try {
      const res = await getEMenuProConfig(sessionKey)
      if (res.res?.data?.result?.successful) {
        const emenuProConfig = res.res?.data.marginAppConfigTypes.find(
          (each) => each.product === 'EMENUPRO'
        )
        if (!emenuProConfig || !emenuProConfig?.data) return
        const dataObj = JSON.parse(emenuProConfig?.data) as IConfigData
        dispatch(
          actions.setInitData(
            dataObj.version ? { ...dataObj, isHasTemplate: true } : initialState
          )
        )
        const { globalData } = dataObj
        const selectedMenu = globalData?.map((g) => {
          return {
            id: Number(g.groupId),
            name: g.groupName,
            menuCategories: g.children?.map((c) => {
              return {
                id: Number(c.categoryId),
                name: c.categoryName,
              }
            }),
          }
        })
        dispatch(
          productGroupingActions.setSelectedMenu(selectedMenu as IGroup[])
        )
      }
    } catch (e) {
      message.warning((e as Error)?.message || 'Failed to fetch config')
    }
  }
  if (__DEV__) {
    await handleFetch(DEV_SESSION_KEY)
    return
  }
  getSessionKeyViaMessage(handleFetch)
}

const saveEMenuProConfig = (): AppThunk => async (dispatch, getState) => {
  const handleSave = async (sessionKey?: string | undefined) => {
    try {
      const {
        version,
        width,
        height,
        viewportWidth,
        viewportHeight,
        direction,
        status,
        globalData,
        globalBlocks,
      } = getState().paletteSlice
      const dataObj = {
        version,
        width,
        height,
        viewportWidth,
        viewportHeight,
        direction,
        status,
        globalData,
        globalBlocks,
        lastUpdateTime: +new Date(),
      }
      if (!globalData.length) {
        message.warning('Please set the template')
        return
      }
      const dataStr = JSON.stringify(dataObj)
      await setEMenuProConfig({
        templateData: dataStr,
        sessionKey,
      })
      await dispatch(effects.fetchEMenuProConfig())
    } catch (e) {
      message.warning((e as Error)?.message || 'Failed to save config')
    }
  }
  if (__DEV__) {
    await handleSave(DEV_SESSION_KEY)
    return
  }
  getSessionKeyViaMessage(handleSave)
}

const deleteCurrentTemplate = (): AppThunk => async (dispatch) => {
  const handleDelete = async (sessionKey?: string | undefined) => {
    try {
      const res = await setEMenuProConfig({ templateData: '{}', sessionKey })
      if (res.res?.data?.result?.successful) {
        await dispatch(effects.fetchEMenuProConfig())
      }
    } catch (e) {
      message.warning((e as Error)?.message || 'Failed to save config')
    }
  }
  if (__DEV__) {
    await handleDelete(DEV_SESSION_KEY)
    return
  }
  getSessionKeyViaMessage(handleDelete)
}

export const effects = {
  fetchEMenuProConfig,
  saveEMenuProConfig,
  deleteCurrentTemplate,
}
