import { useAppDispatch, useTypedSelector } from '@/store'
import styles from './MemberPriceSetting.module.less'
import { useTranslation } from 'react-i18next'
import { CSSProperties, useMemo } from 'react'
import { Space } from 'antd'
import PixelStyleChanger from './PixelStyleChanger'
import { IBusinessComp } from '@/types/template'
import { actions } from '@/store/slices/palette.slice.ts'
import ColorStyleChanger from './ColorStyleChanger'
import BlockUploadImage from './BlockUploadImage'

const MemberPriceSetting = () => {
  const { t } = useTranslation()

  const { currentBlock } = useTypedSelector((state) => state.paletteSlice)
  const dispatch = useAppDispatch()

  const memberPriceIconInfo = useMemo(() => {
    return currentBlock.children?.find(
      (block) => block.component === 'MemberPriceIcon'
    )
  }, [currentBlock])

  const memberPriceValueInfo = useMemo(() => {
    return currentBlock.children?.find(
      (block) => block.component === 'MemberPriceValue'
    )
  }, [currentBlock])

  const syncSubBlockToBlock = (subBlock: IBusinessComp) => {
    const newCurrentBlock = {
      ...currentBlock,
      children: currentBlock.children?.map((b) => {
        return b.component === subBlock.component ? subBlock : b
      }),
    }
    dispatch(actions.setCurrentBlock(newCurrentBlock))
  }

  const changeMemberPriceIconStyle = (newCss: CSSProperties) => {
    if (memberPriceIconInfo) {
      const newMemberPriceIconInfo = {
        ...memberPriceIconInfo,
        style: {
          ...memberPriceIconInfo?.style,
          ...newCss,
        },
      }
      syncSubBlockToBlock(newMemberPriceIconInfo)
    }
  }

  const changeMemberPriceIconImg = (value: string[]) => {
    if (memberPriceIconInfo) {
      const newMemberPriceIconInfo = {
        ...memberPriceIconInfo,
        props: {
          ...memberPriceIconInfo.props,
          imgUrl: value[0],
        },
      }
      syncSubBlockToBlock(newMemberPriceIconInfo)
    }
  }

  const memberPriceIconImgProps = useMemo(() => {
    return {
      fallbackImg: memberPriceIconInfo?.props?.defaultImg || undefined,
      value: memberPriceIconInfo?.props?.imgUrl
        ? [memberPriceIconInfo.props.imgUrl]
        : [],
      onChange: changeMemberPriceIconImg,
      uploadType: 'image',
    }
  }, [memberPriceIconInfo, changeMemberPriceIconImg])

  const changeMemberPriceValueStyle = (newCss: CSSProperties) => {
    if (memberPriceValueInfo) {
      const newMemberPriceValueInfo = {
        ...memberPriceValueInfo,
        style: {
          ...memberPriceValueInfo?.style,
          ...newCss,
        },
      }
      syncSubBlockToBlock(newMemberPriceValueInfo)
    }
  }

  return (
    <div className={styles.memberPriceSetting}>
      <div className={styles.subBlock}>
        <span>{t('blocks.memberPriceIcon_label')}</span>
        <span>{t('blocks.component_property')}</span>
      </div>
      <Space direction="vertical" size={8}>
        <BlockUploadImage {...memberPriceIconImgProps} />
        <PixelStyleChanger
          cssKey={['width', 'height']}
          onChange={changeMemberPriceIconStyle}
          data={{
            style: memberPriceIconInfo?.style || {},
          }}
        />
      </Space>
      <div className={styles.subBlock}>
        <span>{t('blocks.memberPriceValue_label')}</span>
        <span>{t('blocks.component_property')}</span>
      </div>
      <Space direction="vertical" size={8}>
        <PixelStyleChanger
          cssKey={['fontSize']}
          onChange={changeMemberPriceValueStyle}
          data={{
            style: memberPriceValueInfo?.style || {},
          }}
        />
        <ColorStyleChanger
          cssKey={['color']}
          onChange={changeMemberPriceValueStyle}
          data={{
            style: memberPriceValueInfo?.style || {},
          }}
        />
      </Space>
    </div>
  )
}

export default MemberPriceSetting
