import DishTreeSelect from '../MenuTreeSelect/DishTreeSelect.tsx'
import { useAppDispatch, useTypedSelector } from '@/store'
import { actions } from '@/store/slices/palette.slice.ts'
import { useTranslation } from 'react-i18next'
import getCurrentCategoryDish from '@/utils/getCurrentCategoryDish.ts'
import { Col, Row } from 'antd'

const BlockBindDish = () => {
  const { t } = useTranslation()
  const dispatch = useAppDispatch()
  const { currentBlock, currentPageData } = useTypedSelector(
    (state) => state.paletteSlice
  )

  const bindDishToCurrentBlock = (val: string | undefined) => {
    dispatch(actions.editCurrentBlockProps({ itemId: val }))
  }

  return (
    <>
      <Row>
        <Col span={24}>{t('blocks.bind_dish_property')}:</Col>
      </Row>
      <Row>
        <Col span={24}>
          <DishTreeSelect
            value={currentBlock?.props?.itemId || undefined}
            onChange={bindDishToCurrentBlock}
            resolveTreeData={(data) =>
              getCurrentCategoryDish({ currentPageData, data })
            }
          />
        </Col>
      </Row>
    </>
  )
}

export default BlockBindDish
