import ColorStyleChanger from './ColorStyleChanger'
import { useAppDispatch, useTypedSelector } from '@/store'
import { type CSSProperties } from 'react'
import { actions } from '@/store/slices/palette.slice.ts'
import type { CSSKey } from '@/types/block'

interface IProps {
  cssKey?: CSSKey[]
}

const ChangeColor = (props: IProps) => {
  const { cssKey = ['color', 'backgroundColor'] } = props
  const { currentBlock } = useTypedSelector((state) => state.paletteSlice)
  const dispatch = useAppDispatch()

  const onStyleChange = (newSize: CSSProperties) => {
    dispatch(actions.editCurrentBlockStyle(newSize))
  }

  return (
    <ColorStyleChanger
      cssKey={cssKey}
      onChange={onStyleChange}
      data={{
        style: currentBlock.style,
      }}
    />
  )
}

export default ChangeColor
