import type { TreeSelectProps } from 'antd/es/tree-select'
import type { ITemplateData } from '@/types/template'

const getCurrentCategoryDish = ({
  data,
  currentPageData,
}: {
  data: TreeSelectProps['treeData']
  currentPageData: ITemplateData['currentPageData']
}) => {
  const { groupId, categoryId } = currentPageData
  const currentCategoryItems = data
    ?.find((g) => g.value === groupId)
    ?.children?.find((c) => c.value === `${groupId}-${categoryId}`)
  return currentCategoryItems ? [currentCategoryItems] : undefined
}

export default getCurrentCategoryDish
