import { createSlice } from '@reduxjs/toolkit'
import { IMenuSlice } from '@/types/menu'
import { getMenus } from '@/service/menu.ts'
import { message } from 'antd'
import type { PayloadAction } from '@reduxjs/toolkit'
import type { AppThunk } from '@/store'
import { addI18nResources } from '@/utils/addI18nResources'

const initialState: IMenuSlice = {
  menus: [] as IMenuSlice['menus'],
}

export const menuSlice = createSlice({
  name: 'menuSlice',
  initialState,
  reducers: {
    setAllMenus(state, action: PayloadAction<IMenuSlice['menus']>) {
      const menus = action.payload
      const menuGroups = menus?.[0]?.menuGroups
      addI18nResources(menuGroups)
      state.menus = menus
    },
  },
})

export const actions = menuSlice.actions

export default menuSlice.reducer

const fetchMenus = (): AppThunk => async (dispatch) => {
  try {
    const res = await getMenus()
    if (res.res?.data.menus) {
      dispatch(actions.setAllMenus(res.res?.data.menus))
    }
  } catch (e) {
    message.warning((e as Error)?.message || 'Failed to fetch menu')
  }
}

export const effects = {
  fetchMenus,
}
