import { allBlocks, BlockType } from '@/types/block'
import {
  pageBlock,
  addToCartImageBtnBlock,
  soldOutImageBlock,
  shoppingCartBlock,
  homeBlock,
  menuListBlock,
  menuItemBlock,
  expandMenuBlock,
  narrowMenuBlock,
  memberLoginBlock,
  callServerBlock,
  countDownBlock,
  changeLanguageBlock,
  switchBuffetBlock,
  orderIntervalBlock,
  changePartySizeBlock,
  switchTableBlock,
  videoBlock,
  carouselBlock,
  batteryWifiBlock,
  dishNameBlock,
  salePriceBlock,
  memberPriceBlock,
  memberPriceIconBlock,
  memberPriceValueBlock,
} from '@/constants/Blocks.tsx'

class BlockRegister<T extends BlockType> {
  private blocks: Map<T['component'], T>

  constructor() {
    this.blocks = new Map()
  }

  registerBlock(blockObj: T): void {
    this.blocks.set(blockObj.component, blockObj)
  }

  getAllBlocks(): Map<T['component'], T> {
    return this.blocks
  }

  getBlock<K extends T['component']>(
    component: K
  ): Extract<T, { component: K }> {
    return this.blocks.get(component) as Extract<T, { component: K }>
  }
}

const register = new BlockRegister<allBlocks>()

register.registerBlock(pageBlock)
register.registerBlock(addToCartImageBtnBlock)
register.registerBlock(soldOutImageBlock)
register.registerBlock(shoppingCartBlock)
register.registerBlock(homeBlock)
register.registerBlock(menuListBlock)
register.registerBlock(menuItemBlock)
register.registerBlock(expandMenuBlock)
register.registerBlock(narrowMenuBlock)
register.registerBlock(memberLoginBlock)
register.registerBlock(callServerBlock)
register.registerBlock(countDownBlock)
register.registerBlock(orderIntervalBlock)
register.registerBlock(changeLanguageBlock)
register.registerBlock(switchBuffetBlock)
register.registerBlock(switchTableBlock)
register.registerBlock(changePartySizeBlock)
register.registerBlock(videoBlock)
register.registerBlock(carouselBlock)
register.registerBlock(batteryWifiBlock)
register.registerBlock(dishNameBlock)
register.registerBlock(salePriceBlock)
register.registerBlock(memberPriceBlock)
register.registerBlock(memberPriceIconBlock)
register.registerBlock(memberPriceValueBlock)

export default register
