import { type CSSProperties, useMemo, memo } from 'react'
import type { IRenderBlockInfo } from '@/types/block'

const MenuItem = (props: IRenderBlockInfo) => {
  const { style, data } = props

  const categoryName = useMemo(() => {
    if (typeof data?.categoryName === 'string') {
      return data?.categoryName
    }
    return ''
  }, [data])

  const extraStyle: CSSProperties = useMemo(() => {
    return data?.isVertical
      ? {
          display: '-webkit-box',
          WebkitBoxOrient: 'vertical',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
        }
      : {}
  }, [data?.isVertical])

  return (
    <div
      style={{
        ...style,
        paddingTop: 0,
        paddingBottom: 0,
        paddingRight: 0,
        paddingLeft: 0,
        color: 'inherit',
        backgroundColor: 'inherit',
        ...extraStyle,
      }}
    >
      {categoryName}
    </div>
  )
}

export default memo(MenuItem)
