import { useTypedSelector } from '@/store'
import { useMemo } from 'react'
import MenuTreeSelect from './index'
import type { TreeSelectProps } from 'antd/es/tree-select'
import { useTranslation } from 'react-i18next'

interface IProps {
  value: string | undefined
  onChange: (val: string) => void
  resolveTreeData?: (data: TreeSelectProps['treeData']) => typeof data
}

const DishTreeSelect = (props: IProps) => {
  const { t } = useTranslation()
  const { value, onChange, resolveTreeData } = props
  const { menus } = useTypedSelector((state) => state.menuSlice)

  const treeData = useMemo(() => {
    return menus[0]?.menuGroups?.map((g) => {
      return {
        value: `${g.id}`,
        title: t(`${g.id}`, { ns: 'group' }),
        selectable: false,
        children: g.menuCategories?.map((c) => {
          return {
            value: `${g.id}-${c.id}`,
            title: t(`${c.id}`, { ns: 'category' }),
            selectable: false,
            children: c?.saleItems?.map((i) => {
              return {
                value: `${i.id}`,
                title: t(`${i.id}`, { ns: 'dish' }),
              }
            }),
          }
        }),
      }
    })
  }, [menus, t])

  const handleChangeBindDish = (val: string | undefined) => {
    onChange(typeof val === 'string' ? val : '')
  }

  return (
    <MenuTreeSelect
      value={value}
      treeData={resolveTreeData ? resolveTreeData(treeData) : treeData}
      onChange={handleChangeBindDish}
      multiple={false}
    />
  )
}

export default DishTreeSelect
