import {
  configureStore,
  combineReducers,
  ThunkAction,
  Action,
} from '@reduxjs/toolkit'
import paletteSlice from './slices/palette.slice.ts'
import productGroupingSlice from './slices/productGrouping.slice.ts'
import menuSlice from './slices/menu.slice.ts'
import { TypedUseSelectorHook, useDispatch, useSelector } from 'react-redux'

const rootReducer = combineReducers({
  paletteSlice,
  productGroupingSlice,
  menuSlice,
})

const store = configureStore({
  reducer: rootReducer,
})

export default store

export type AppState = ReturnType<typeof rootReducer>
export type AppDispatch = typeof store.dispatch
export type AppThunk<T = void> = ThunkAction<
  Promise<T>,
  AppState,
  unknown,
  Action<string>
>

export const useAppDispatch = () => useDispatch<AppDispatch>()
export const useTypedSelector: TypedUseSelectorHook<AppState> = useSelector
