import { serverUrl } from '@/constants/env.ts'
import { ImgHTMLAttributes, useMemo } from 'react'

export interface ImageProps extends ImgHTMLAttributes<HTMLImageElement> {
  fallbackImg?: string
}

const Image = (props: ImageProps) => {
  const { alt, src, fallbackImg, ...rest } = props

  const isLocalDefault = useMemo(() => {
    return !__DEV__ && fallbackImg?.includes('/images/')
  }, [fallbackImg])

  const localDefaultImgSrc = useMemo(() => {
    if (isLocalDefault) {
      const fallbackImgArray = fallbackImg?.split('/')
      const imageName = fallbackImgArray?.[fallbackImgArray?.length - 1]
      return `/kpos/emenuPro/images/${imageName}`
    }
  }, [fallbackImg, isLocalDefault])

  return (
    <img
      {...rest}
      alt={alt}
      src={
        src
          ? `${serverUrl}${src}`
          : `${isLocalDefault ? localDefaultImgSrc : fallbackImg}`
      }
    />
  )
}

export default Image
