import { Post } from '@/utils/request.ts'
import { ISettingConfig } from '@/types/service'

export function getEMenuProConfig(sessionKey?: string | undefined) {
  const data = {
    product: 'EMENUPRO',
    userAuth: {
      sessionKey,
    },
  }
  return Post<ISettingConfig>(
    `${
      import.meta.env.DEV
        ? `${import.meta.env.VITE_SERVER_URL}webapp`
        : '/kpos/webapp'
    }/marginapp/fetchConfig`,
    data,
    {
      baseURL: '/',
    }
  )
}

export function setEMenuProConfig({
  templateData = '{}',
  sessionKey = undefined,
}: {
  templateData: string
  sessionKey?: string | undefined
}) {
  const data = {
    marginAppConfigType: {
      product: 'EMENUPRO',
      data: templateData,
    },
    userAuth: {
      sessionKey,
    },
  }
  return Post<ISettingConfig>(
    `${
      import.meta.env.DEV
        ? `${import.meta.env.VITE_SERVER_URL}webapp`
        : '/kpos/webapp'
    }/marginapp/config`,
    data,
    {
      baseURL: '/',
    }
  )
}
