import register from '@/utils/blockRegister.ts'
import { useTypedSelector } from '@/store'
import { useMemo, memo } from 'react'
import type { IRenderBlockInfo } from '@/types/block'
import { useTranslation } from 'react-i18next'

const MenuList = (props: IRenderBlockInfo) => {
  const { t } = useTranslation()
  const { style, children } = props
  const { globalData } = useTypedSelector((state) => state.paletteSlice)

  const categoryNames = useMemo(() => {
    return globalData.reduce((pre, cur) => {
      const groupCategory = cur.children.map((c) =>
        t(`${c.categoryId}`, { ns: 'category' })
      )
      return pre.concat(...groupCategory)
    }, [] as string[])
  }, [globalData, t])

  const menuItemInfo = useMemo(() => {
    return children?.find((block) => block.component === 'MenuItem')
  }, [children])

  return (
    <div
      style={{
        ...style,
        color: menuItemInfo?.style.color,
        backgroundColor: menuItemInfo?.style.backgroundColor,
      }}
    >
      {children?.map((block) => {
        const { component } = block
        const blockInfo = register.getBlock(component)
        if (component === 'MenuItem') {
          return categoryNames.map((c, i) => {
            return (
              <div
                style={{
                  width: block.style.width,
                  height: block.style.height,
                  paddingTop: block.style.paddingTop,
                  paddingRight: block.style.paddingRight,
                  paddingBottom: block.style.paddingBottom,
                  paddingLeft: block.style.paddingLeft,
                  backgroundColor:
                    i === 1
                      ? block.props?.active?.style?.backgroundColor
                      : 'transparent',
                  color:
                    i === 1 ? block.props?.active?.style?.color : style.color,
                }}
                key={c}
              >
                {blockInfo.render({
                  ...block,
                  data: {
                    categoryName: c,
                    isVertical: props.props?.direction === 'vertical',
                  },
                })}
              </div>
            )
          })
        }
        return null
      })}
    </div>
  )
}

export default memo(MenuList)
