import getCssValue from './getCssValue.ts'
import store from '@/store'
import React from 'react'

export const isPercentage = (str: string) => {
  return /^-?\d+(\.\d+)?%$/.test(str.trim())
}

export const checkPositionLeft = (
  width: React.CSSProperties['width'],
  left: number | string
) => {
  const cssWidth = getCssValue(width)
  const cssLeft = getCssValue(left)
  const minLeft = 0
  const maxLeft = store.getState().paletteSlice.viewportWidth - cssWidth
  return cssLeft >= maxLeft ? maxLeft : cssLeft <= minLeft ? minLeft : cssLeft
}

export const checkPositionTop = (
  height: React.CSSProperties['height'],
  top: number | string
) => {
  const cssHeight = getCssValue(height)
  const cssTop = getCssValue(top)
  const minTop = 0
  const maxTop = store.getState().paletteSlice.viewportHeight - cssHeight
  return cssTop >= maxTop ? maxTop : cssTop <= minTop ? minTop : cssTop
}

export const checkBlockWidth = (width: React.CSSProperties['width']) => {
  if (typeof width === 'string' && isPercentage(width)) return width
  const cssWidth = getCssValue(width)
  const maxWidth = store.getState().paletteSlice.viewportWidth
  return cssWidth >= maxWidth ? maxWidth : cssWidth
}

export const checkBlockHeight = (height: React.CSSProperties['height']) => {
  if (typeof height === 'string' && isPercentage(height)) return height
  const cssHeight = getCssValue(height)
  const maxHeight = store.getState().paletteSlice.viewportHeight
  return cssHeight >= maxHeight ? maxHeight : cssHeight
}

export const haveOptionsPrice = (
  list?: { price?: number; subOptions?: { price?: number }[] }[]
) => {
  if (!Array.isArray(list)) return false
  return list.some((item) => {
    if ((item.price ?? 0) > 0) return true
    if (item.subOptions && haveOptionsPrice(item.subOptions)) return true
    return false
  })
}
