import { message } from 'antd'
import axios, { AxiosError, AxiosRequestConfig } from 'axios'

export const TIMEOUT = 20 // 超时时间,单位 s

export interface ErrorWrap<T> {
  res?: IResponse<T>
  err?: Error
}

export interface IResponse<T> {
  data: T
  code: number
  msg: string
}

const instance = axios.create({
  baseURL: '/kpos/api',
  timeout: TIMEOUT * 1000,
  validateStatus: (status) => status < 500, // 默认是 [200,300)
})

/** 错误处理 */
instance.interceptors.response.use(
  // status < 500
  (response) => {
    const { data, status } = response
    // 兼容上传图片接口
    if (
      response?.config?.url?.includes('/file/image/') &&
      data === 'Image has been successfully uploaded'
    ) {
      const newData = {
        code: 0,
        msg: 'success',
        data: 'Image has been successfully uploaded',
      }
      response.data = newData
      return response
    }
    if (
      response?.config?.url?.includes('/webapp/marginapp/') &&
      data?.result?.successful
    ) {
      const newData = {
        code: 0,
        msg: 'success',
        data,
      }
      response.data = newData
      return response
    }
    if (status !== 200) throw Error(data?.message)
    if (data.code !== 0)
      throw Error(data?.message || data?.msg || data?.result?.failureReason)

    return response
  },
  // status >= 500
  (error: AxiosError<{ message: string }>) => {
    // 有返回data,但不是 200
    if (error.response) {
      const { data } = error.response
      throw Error(data?.message)
    }

    // 断网
    if (!window.navigator.onLine) {
      throw Error('Network Error! Please check your network.')
    }

    return Promise.reject(error)
  }
)

async function request<T>(
  url: string,
  config: AxiosRequestConfig
): Promise<ErrorWrap<T>> {
  const { method = 'POST', headers, data: requestData, ...restConfig } = config
  try {
    const params = {
      url,
      method,
      headers: {
        ...headers,
        Authorization: !url.includes('/kpos/webapp')
          ? 'UvDU853J9L351BThAC'
          : undefined,
      },
      [method === 'GET' ? 'params' : 'data']: requestData,
      ...restConfig,
    }
    const { data } = await instance.request<IResponse<T>>(params)
    return { res: data }
  } catch (error) {
    const err = error as Error
    message.warning(err.message)
    return { err }
  }
}

function Post<T>(uri: string, data?: object, config?: AxiosRequestConfig) {
  return request<T>(uri, { method: 'POST', data, ...config })
}

function Get<T>(uri: string, data?: object, config?: AxiosRequestConfig) {
  return request<T>(uri, { method: 'GET', data, ...config })
}

request.instance = instance

export { Post, Get }
export default request
