import { memo } from 'react'
import ImageCoreBlock from '@/components/CoreBlock/ImageCoreBlock'
import { useTypedSelector } from '@/store'
import type { IRenderBlockInfo } from '@/types/block'

const Page = (props: IRenderBlockInfo) => {
  const { style, props: blockProps } = props
  const { aspectRatio } = useTypedSelector((state) => state.paletteSlice)

  return blockProps?.imgUrl ? (
    <ImageCoreBlock
      src={blockProps?.imgUrl}
      style={{ ...style, aspectRatio }}
      alt="container background image"
    />
  ) : null
}

export default memo(Page)
