import { Button, Col, Radio, Row, Space } from 'antd'
import { useAppDispatch, useTypedSelector } from '@/store'
import { actions } from '@/store/slices/palette.slice.ts'
import { type CSSProperties, useEffect, useMemo } from 'react'
import styles from './MenuListSetting.module.less'
import { useTranslation } from 'react-i18next'
import PixelStyleChanger from './PixelStyleChanger'
import ColorStyleChanger from './ColorStyleChanger'
import type { IBusinessComp, OverWriteStyleProps } from '@/types/template'
import type { RadioGroupProps } from 'antd/es/radio'
import {
  generateMenuIndicator,
  generateMenuItemProps,
  menuListInitProps,
} from '@/constants/BlockProperties'
import {
  horizontalExpandMenuStyle,
  horizontalMenuItemStyle,
  horizontalMenuListStyle,
  horizontalNarrowMenuStyle,
  verticalExpandMenuStyle,
  verticalMenuItemStyle,
  verticalMenuListStyle,
  verticalNarrowMenuStyle,
} from '@/constants/BlockInitStyle.ts'
import type { CSSKey } from '@/types/block'
import ChangeLineClamp from './ChangeLineClamp.tsx'
import getCssValue from '@/utils/getCssValue.ts'

const { Group: RadioGroup } = Radio

const MenuListSetting = () => {
  const { t } = useTranslation()
  const { currentBlock, globalBlocks, viewportHeight, viewportWidth } =
    useTypedSelector((state) => state.paletteSlice)
  const dispatch = useAppDispatch()

  useEffect(() => {
    if (currentBlock.component === 'MenuList') {
      if (currentBlock.props?.direction === 'vertical') {
        const narrowButtonNewLeft = getCssValue(currentBlock?.style?.width)
        changeNarrowButtonPosition({
          left: narrowButtonNewLeft,
        })
      }
      if (currentBlock.props?.direction === 'horizontal') {
        const narrowButtonNewTop = getCssValue(currentBlock?.style?.height)
        changeNarrowButtonPosition({
          top: narrowButtonNewTop,
        })
      }
    }
  }, [
    currentBlock?.component,
    currentBlock?.style?.width,
    currentBlock?.style?.height,
    currentBlock?.props?.direction,
  ])

  const menuItemInfo = useMemo(() => {
    return currentBlock.children?.find(
      (block) => block.component === 'MenuItem'
    )
  }, [currentBlock])

  const changeNarrowButtonPosition = (newStyle: CSSProperties) => {
    const narrowButtonBlock = globalBlocks?.find(
      (b) => b.component === 'NarrowMenu'
    )
    if (narrowButtonBlock) {
      //syncGlobalBlocks
      dispatch(
        actions.syncGlobalBlocks({
          ...narrowButtonBlock,
          style: {
            ...narrowButtonBlock.style,
            ...newStyle,
          },
        })
      )
    }
  }

  const syncSubBlockToBlock = (subBlock: IBusinessComp) => {
    const newCurrentBlock = {
      ...currentBlock,
      children: currentBlock.children?.map((b) => {
        return b.component === subBlock.component ? subBlock : b
      }),
    }
    dispatch(actions.setCurrentBlock(newCurrentBlock))
  }

  const changeMenuItemStyle = (newCss: CSSProperties) => {
    if (menuItemInfo) {
      const newMenuItemInfo = {
        ...menuItemInfo,
        style: {
          ...menuItemInfo?.style,
          ...newCss,
        },
      }
      syncSubBlockToBlock(newMenuItemInfo)
    }
  }

  const changeMenuItemActiveStyle = (newCss: CSSProperties) => {
    if (menuItemInfo) {
      const newMenuItemInfo = {
        ...menuItemInfo,
        props: {
          ...menuItemInfo.props,
          active: {
            ...menuItemInfo?.props?.active,
            style: {
              ...menuItemInfo?.props?.active?.style,
              ...newCss,
            },
          },
        },
      }
      syncSubBlockToBlock(newMenuItemInfo)
    }
  }

  const handleChangeDirection: RadioGroupProps['onChange'] = (v) => {
    const isVertical = v.target.value === 'vertical'

    const newCurrentBlock = {
      ...currentBlock,
      style: isVertical ? verticalMenuListStyle : horizontalMenuListStyle,
      props: {
        ...currentBlock.props,
        ...menuListInitProps,
        direction: v.target.value,
        overWriteStyleProps: isVertical
          ? undefined
          : ({
              changeSize: {
                cssKey: [
                  'width',
                  'height',
                  'borderBottomRightRadius',
                  'borderBottomLeftRadius',
                ],
              },
              changePosition: {
                cssKey: ['left'],
              },
            } as OverWriteStyleProps),
      },
      children: currentBlock.children?.map((b) => {
        if (b.component === 'MenuItem') {
          return {
            ...b,
            style: isVertical ? verticalMenuItemStyle : horizontalMenuItemStyle,
            props: generateMenuItemProps(),
          }
        }
        return b
      }),
    }
    dispatch(actions.setCurrentBlock(newCurrentBlock))
    if (currentBlock?.props?.linkIds?.length) {
      const newGlobalBlock = globalBlocks?.map((b) => {
        if (currentBlock?.props?.linkIds?.includes(b.id)) {
          if (b.component === 'ExpandMenu') {
            return {
              ...b,
              style: isVertical
                ? verticalExpandMenuStyle
                : horizontalExpandMenuStyle,
              props: {
                ...b.props,
                ...generateMenuIndicator('expand', v.target.value),
                overWriteStyleProps: isVertical
                  ? undefined
                  : ({
                      changePosition: {
                        cssKey: ['left'],
                      },
                    } as OverWriteStyleProps),
              },
            }
          }
          if (b.component === 'NarrowMenu') {
            return {
              ...b,
              style: isVertical
                ? verticalNarrowMenuStyle
                : horizontalNarrowMenuStyle,
              props: {
                ...b.props,
                ...generateMenuIndicator('narrow', v.target.value),
                overWriteStyleProps: isVertical
                  ? undefined
                  : ({
                      changePosition: {
                        cssKey: ['left'],
                      },
                    } as OverWriteStyleProps),
              },
            }
          }
        }
        return b
      })
      dispatch(actions.setGlobalBlocks(newGlobalBlock))
    }
  }

  const isVertical = useMemo(() => {
    return currentBlock.props?.direction === 'vertical'
  }, [currentBlock.props?.direction])

  const subBlockStyleCssKey: CSSKey[] = useMemo(() => {
    return isVertical
      ? [
          'paddingTop',
          'paddingRight',
          'paddingBottom',
          'paddingLeft',
          'fontSize',
        ]
      : ['paddingRight', 'paddingLeft', 'fontSize']
  }, [isVertical])

  const handleCenterMenu = () => {
    const generateTopLeftCenter = (block: IBusinessComp) => {
      return {
        top: isVertical
          ? viewportHeight / 2 - getCssValue(block.style.height) / 2
          : block.style.top,
        left: isVertical
          ? block.style.left
          : viewportWidth / 2 - getCssValue(block.style.width) / 2,
      }
    }
    dispatch(actions.editCurrentBlockStyle(generateTopLeftCenter(currentBlock)))
    const newGlobalBlock = globalBlocks?.map((b) => {
      if (currentBlock?.props?.linkIds?.includes(b.id)) {
        return {
          ...b,
          style: {
            ...b.style,
            ...generateTopLeftCenter(b),
          },
        }
      }
      return b
    })
    dispatch(actions.setGlobalBlocks(newGlobalBlock))
  }

  return (
    <div className={styles.menuListSetting}>
      <Row align="middle">
        <Col span={10}>{t('blocks.props_direction')}:</Col>
        <Col span={14}>
          <RadioGroup
            value={currentBlock.props?.direction}
            onChange={handleChangeDirection}
          >
            <Radio value="horizontal">
              {t('blocks.props_direction_horizontal')}
            </Radio>
            <Radio value="vertical">
              {t('blocks.props_direction_vertical')}
            </Radio>
          </RadioGroup>
        </Col>
      </Row>
      <Row align="middle">
        <Col offset={10} span={14}>
          <Button size="small" onClick={handleCenterMenu}>
            {t(
              isVertical ? 'blocks.center_vertical' : 'blocks.center_horizontal'
            )}
          </Button>
        </Col>
      </Row>
      <div className={styles.subBlock}> {t('blocks.prop_sub_block')} </div>
      <Space direction="vertical" size={8}>
        <PixelStyleChanger
          cssKey={subBlockStyleCssKey}
          onChange={changeMenuItemStyle}
          data={{
            style: menuItemInfo?.style || {},
          }}
        />
        {isVertical && (
          <ChangeLineClamp
            value={menuItemInfo?.style?.WebkitLineClamp as number}
            onChange={changeMenuItemStyle}
          />
        )}
      </Space>
      <div className={styles.subBlock}> {t('blocks.active_style')} </div>
      <Space direction="vertical" size={8}>
        <ColorStyleChanger
          cssKey={['color', 'backgroundColor']}
          onChange={changeMenuItemActiveStyle}
          data={{
            style: {
              backgroundColor:
                menuItemInfo?.props?.active?.style?.backgroundColor,
              color: menuItemInfo?.props?.active?.style?.color,
            },
          }}
        />
      </Space>
      <div className={styles.subBlock}> {t('blocks.none_active_style')} </div>
      <Space direction="vertical" size={8}>
        <ColorStyleChanger
          cssKey={['color', 'backgroundColor']}
          onChange={changeMenuItemStyle}
          data={{
            style: {
              backgroundColor: menuItemInfo?.style?.backgroundColor,
              color: menuItemInfo?.style?.color,
            },
          }}
        />
      </Space>
    </div>
  )
}

export default MenuListSetting
