export const generateMenuItemProps = () => {
  return {
    imgUrl: '',
    defaultImg: '',
    active: {
      style: {
        backgroundColor: '#E3C18A',
        color: '#000',
      },
    },
    events: [
      {
        event: 'onClick',
        trigger: 'click',
        actions: [
          {
            type: 'jumpToCategory',
          },
        ],
      },
    ],
  }
}

export const menuItemInitProps = generateMenuItemProps()

export const generateMenuIndicator = (
  type = 'expand',
  direction = 'vertical'
) => {
  const defaultImg = `/images/${type}_${direction}.png`
  return {
    imgUrl: '',
    defaultImg,
    events: [
      {
        event: 'onClick',
        trigger: 'click',
        actions: [
          {
            type: type === 'expand' ? 'openMenu' : 'hideMenu',
          },
        ],
      },
    ],
    direction: direction as Direction,
  }
}
export const expandMenuInitProps = generateMenuIndicator('expand', 'vertical')
export const narrowMenuInitProps = generateMenuIndicator('narrow', 'vertical')

