import type { CSSProperties } from 'react'
import { useTranslation } from 'react-i18next'
import { Col, InputNumber, Row } from 'antd'

interface IProps {
  value: number
  onChange: (css: CSSProperties) => void
}

const ChangeLineClamp = (props: IProps) => {
  const { value, onChange } = props
  const { t } = useTranslation()

  return (
    <Row align="middle">
      <Col span={10}>{t('style.WebkitLineClamp')}:</Col>
      <Col span={14}>
        <InputNumber
          value={value}
          step={1}
          min={1}
          max={9999}
          onChange={(v) => onChange({ WebkitLineClamp: v || 1 })}
          addonAfter={t('style.lines')}
        />
      </Col>
    </Row>
  )
}

export default ChangeLineClamp
