const renderBlock: BlockType['render'] = (props) => {
  const blockMap = {
    Page,
    AddToCartImageBtn,
    SoldOutImage,
    ShoppingCart,
    Home,
    MenuList: Menu.MenuList,
    MenuItem: Menu.MenuItem,
    ExpandMenu: Menu.MenuIndicator,
    NarrowMenu: Menu.MenuIndicator,
    MemberLogin,
    CallServer,
    ChangeLanguage,
    SwitchBuffet,
    CountDown,
    OrderInterval,
    SwitchTable,
    ChangePartySize,
    Video,
    Carousel,
    BatteryWifi,
    DishName,
    SalePrice,
    MemberPrice: MemberPrice.MemberPrice,
    MemberPriceIcon: MemberPrice.MemberPriceIcon,
    MemberPriceValue: MemberPrice.MemberPriceValue,
  }
  const Node = blockMap[props.component]
  const { style, ...rest } = props
  return (
    <Node key={props.id} {...rest} style={{ ...style, ...blockDefaultStyle }} />
  )
}

export const pageBlock: PageBlock = {
  label: 'blocks.page_label',
  component: 'Page',
  render: (props) => renderBlock(props),
  resizable: false,
  draggable: false,
  properties: ['uploadImage'],
  style: initPageBlockStyle,
  isHideInList: true,
  isNeedTooltipBar: false,
  isGlobalBlock: false,
}

