import UploadWithForm from '../UploadWithForm'
import { useAppDispatch, useTypedSelector } from '@/store'
import { actions } from '@/store/slices/palette.slice.ts'
import { useTranslation } from 'react-i18next'
import { Col, Row } from 'antd'

const { UploadVideo } = UploadWithForm

const Uploader = () => {
  const { t } = useTranslation()
  const { currentBlock, width, height } = useTypedSelector(
    (state) => state.paletteSlice
  )

  const dispatch = useAppDispatch()

  const uploadImageToCurrentBlock = (val: string[]) => {
    const videoUrl = val?.[0]
    dispatch(actions.editCurrentBlockProps({ videoUrl }))
  }

  return (
    <Row align="middle">
      <Col span={10}>{t('operation.upload')}:</Col>
      <Col span={14}>
        <UploadVideo
          value={
            (currentBlock?.props?.videoUrl
              ? [currentBlock?.props?.videoUrl]
              : []) as string[]
          }
          onChange={uploadImageToCurrentBlock}
          uploadConfig={{
            maxCount: 1,
            multiple: false,
          }}
          showImageDimensions={true}
          maxDimensions={{
            width,
            height,
          }}
        />
      </Col>
    </Row>
  )
}

const BlockUploadVideo = () => {
  return <Uploader />
}

export default BlockUploadVideo
