import PixelStyleChanger from './PixelStyleChanger'
import { useAppDispatch, useTypedSelector } from '@/store'
import { type CSSProperties } from 'react'
import { actions } from '@/store/slices/palette.slice.ts'
import type { CSSKey } from '@/types/block'

interface IProps {
  cssKey?: CSSKey[]
}

const ChangeSize = (props: IProps) => {
  const { cssKey = ['width', 'height'] } = props
  const { currentBlock, viewportWidth, viewportHeight } = useTypedSelector(
    (state) => state.paletteSlice
  )
  const dispatch = useAppDispatch()

  const onSizeChange = (newSize: CSSProperties) => {
    dispatch(actions.editCurrentBlockStyle(newSize))
  }

  return (
    <PixelStyleChanger
      cssKey={cssKey}
      onChange={onSizeChange}
      data={{
        style: currentBlock.style,
        min: {
          width: currentBlock.style.minWidth,
          height: currentBlock.style.minHeight,
        },
        max: {
          width: viewportWidth,
          height: viewportHeight,
        },
      }}
    />
  )
}

export default ChangeSize
