import { useAppDispatch, useTypedSelector } from '@/store'
import { Col, InputNumber, Row } from 'antd'
import { useTranslation } from 'react-i18next'
import { useMemo } from 'react'
import { actions } from '@/store/slices/palette.slice.ts'

const ChangeOpacity = () => {
  const { t } = useTranslation()
  const { currentBlock } = useTypedSelector((state) => state.paletteSlice)
  const dispatch = useAppDispatch()

  const opacityPercentage = useMemo(() => {
    return Number(currentBlock.style?.opacity ?? 0) * 100
  }, [currentBlock])

  const onOpacityChange = (v: number | null) => {
    const actualOpacity = (v ?? 0) / 100
    dispatch(
      actions.editCurrentBlockStyle({
        opacity: actualOpacity,
      })
    )
  }

  return (
    <Row align="middle">
      <Col span={10}>{t('style.opacity')}:</Col>
      <Col span={14}>
        <InputNumber
          value={opacityPercentage}
          step={1}
          min={0}
          max={100}
          onChange={(v) => onOpacityChange(v)}
          addonAfter="%"
        />
      </Col>
    </Row>
  )
}

export default ChangeOpacity
