import { useTypedSelector } from '@/store'
import { IRenderBlockInfo } from '@/types/block'
import { useMemo } from 'react'

const MemberPriceValue = (props: IRenderBlockInfo) => {
  const { style, props: blockProps, data } = props
  const { menus } = useTypedSelector((state) => state.menuSlice)

  const currentDish = useMemo(() => {
    const allDishes = menus[0]?.menuGroups?.flatMap((group) =>
      group.menuCategories?.flatMap((category) => category.saleItems)
    )
    return allDishes?.find((dish) => dish?.id === Number(data?.itemId))
  }, [menus, data?.itemId])

  const displayText = useMemo(() => {
    if (!currentDish) {
      return '$0.00'
    }

    const { benefitPrice: originBenefitPrice, itemPrices } = currentDish ?? {}
    const benefitPrice =
      itemPrices?.length && itemPrices.length >= 1
        ? itemPrices?.[0]?.benefitPrice
        : originBenefitPrice
    if (benefitPrice !== undefined && benefitPrice >= 0) {
      return `$${benefitPrice.toFixed(2)}`
    }
    const detailBenefitPrices = itemPrices?.reduce(
      (acc: number | undefined, item) => {
        if (item.benefitPrice !== undefined && item.benefitPrice >= 0) {
          if (acc === undefined) {
            acc = item.benefitPrice
          } else {
            acc = Math.min(acc, item.benefitPrice)
          }
        }
        return acc
      },
      undefined
    )
    if (detailBenefitPrices !== undefined) {
      return `$${detailBenefitPrices.toFixed(2)}+`
    }
    return blockProps?.defaultText as string
  }, [currentDish, blockProps])

  return (
    <div style={{ ...style, height: 'none' }}>
      <span>{displayText}</span>
    </div>
  )
}

export default MemberPriceValue
